import { Component, Element, Event, EventEmitter, h, Host, Listen, Method, Prop, State, Watch } from '@stencil/core';
import { FormDataEvent, FormSize, LimitedSeverity } from '../../types';
import { FocusHelper } from '../../utils/focus-helper';

/**
 * @slot default - default slot for the content of the checkbox
 * @nativeEvent click  - dispatched when checkbox was clicked => 'event.target.value' delivers the value & 'event.target.checked' the state of the checkbox
 * @nativeEvent change - dispatched when checkbox has changed => 'event.target.value' delivers the value & 'event.target.checked' the state of the checkbox
 */
@Component({
  tag: 'groupui-checkbox',
  styleUrl: 'checkbox.scss',
  shadow: true,
})
export class Checkbox {
  /**
   * severity of the checkbox
   */
  @Prop({ reflect: true, mutable: true }) severity: LimitedSeverity = 'none';

  /**
   * checked status of the checkbox
   */
  @Prop({ reflect: true, mutable: true }) checked: boolean = false;

  /**
   * indeterminate status of the checkbox, exists next to checked and overrides it
   */
  @Prop({ mutable: true, reflect: true }) indeterminate: boolean = false;

  /**
   * disabled status of the checkbox
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * name of the checkbox component to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * specifies that a checkbox must be checked before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * value part of the name/value pair associated with this element for the purposes of form submission.
   */
  @Prop({ reflect: true }) readonly value: string = 'on';

  /**
   * deactivate internal validations
   */
  @Prop({ reflect: true }) readonly noValidation: boolean;

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * sets the checkbox size
   */
  @Prop({ reflect: false }) readonly size: FormSize = 'm';

  /**
   * for react user only - is dispatched when the checked state is changed
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() focusType: string = '';

  @State() invalid: boolean;

  @Listen('click', { capture: true })
  onClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  @Listen('click')
  handleClick() {
    if (this.disabled) {
      return;
    }
    if (this.indeterminate) {
      this.checked = true;
      this.indeterminate = false;
    } else {
      this.checked = !this.checked;
    }

    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
    this.focusType = '';
  }

  @Watch('checked')
  onCheckedChanged() {
    this.validateCheckbox();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Space') {
      event.preventDefault();
    }
  }

  @Listen('keyup')
  handleSpace(event: KeyboardEvent) {
    if (event.code === 'Space') {
      this.handleClick();
    }
    this.focusType = FocusHelper.onKeyUp(this.focusType, event);
  }

  @Listen('blur')
  onBlur() {
    this.focusType = FocusHelper.onBlur();
    this.validateCheckbox();
  }

  @Listen('focusout')
  onFocusOut() {
    this.host.shadowRoot.getElementById('checkbox').classList.remove('keyboard');
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.validateCheckbox({ force: true });
  }

  componentWillLoad() {
    this.initFormsHandling();
  }

  componentDidLoad() {
    this.autofocus && this.host.focus && this.host.focus();
    this.groupuiDidLoad.emit();
    this.validity = this.getValidity();
  }

  private initFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      if (this.checked) {
        event.formData.append(this.name, this.value);
      }
    });

    form.addEventListener('submit', (event) => {
      this.validateCheckbox();
      if (this.invalid) {
        event.preventDefault();
      }
    });
  }

  private validateCheckbox = ({ force = false }: { force?: boolean } = {}) => {
    if (!force && this.noValidation) return;
    this.invalid = !this.getValidity().valid;
  };

  private getValidity() {
    return {
      valid: this.checked || !this.required,
      valueMissing: this.required && !this.checked,
      badInput: false,
      customError: false,
      patternMismatch: false,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooLong: false,
      tooShort: false,
      typeMismatch: false,
    };
  }

  @Watch('invalid')
  onInvalidChange() {
    this.validity = this.getValidity();
    if (this.invalid) {
      this.severity = 'danger';
      this.host.dispatchEvent(new window.Event('invalid'));
      this.groupuiInvalid.emit();
    } else {
      this.severity = 'none';
    }
  }

  private slotContainsText() {
    const htmlSlotElement = this.host.querySelector('slot:not([name])') as HTMLSlotElement;
    return htmlSlotElement?.assignedNodes().length > 0 || this.host.textContent.trim().length > 0;
  }

  render() {
    return (
      <Host tabIndex={this.disabled ? -1 : 0}>
        <div id="container">
          <div
            id="checkbox"
            class={this.focusType}
            role="checkbox"
            aria-labelledby="label"
            aria-checked={this.checked && !this.indeterminate ? 'true' : 'false'}
          >
            {this.checked && !this.indeterminate && <groupui-icon id="checked" name="check-16" />}
            {this.indeterminate && <groupui-icon id="indeterminate" name="minus-16" />}
          </div>
          {this.slotContainsText() && (
            <div id="label">
              <slot />
            </div>
          )}
        </div>
      </Host>
    );
  }
}
